use crate::meta::ctstring::AsCtString;
use crate::meta::derive_via;

/// Compare two values for equality
///
/// `Eq` provides the `==` and `!=` operators. It is implemented for [`Field`], the integer types,
/// `bool`, `str`, arrays, vectors and tuples of `Eq` types, and can be derived with
/// `#[derive(Eq)]`, which compares every field of a struct.
///
/// Example:
///
/// ```noir
/// #[derive(Eq)]
/// struct Point {
///     x: Field,
///     y: Field,
/// }
///
/// fn main() {
///     assert(Point { x: 1, y: 2 } == Point { x: 1, y: 2 });
///     assert(Point { x: 1, y: 2 } != Point { x: 2, y: 1 });
/// }
/// ```
#[derive_via(derive_eq)]
// docs:start:eq-trait
pub trait Eq {
    /// Returns `true` if `self` and `other` are equal. `a == b` calls `a.eq(b)`.
    fn eq(self, other: Self) -> bool;
}
// docs:end:eq-trait

// docs:start:derive_eq
comptime fn derive_eq(s: TypeDefinition) -> Quoted {
    let signature = quote { fn eq(_self: Self, _other: Self) -> bool };
    let for_each_field = |name| quote { (_self.$name == _other.$name) };
    let body = |fields| {
        if s.fields_as_written().len() == 0 {
            quote { true }
        } else {
            fields
        }
    };
    crate::meta::make_trait_impl(
        s,
        quote { $crate::cmp::Eq },
        signature,
        for_each_field,
        quote { & },
        body,
    )
}
// docs:end:derive_eq

impl Eq for Field {
    fn eq(self, other: Field) -> bool {
        self == other
    }
}

